window.RP_SESSION={"id":"S-15c599acb3d0","messages":[{"id":"RP-0246917","time":"2026-08-23T05:07:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":".","characters":["P-ed77659dbe40"]},{"id":"RP-0246918","time":"2026-08-23T05:07:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":".","characters":["P-ed77659dbe40"]},{"id":"RP-0246919","time":"2026-08-23T05:07:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":".","characters":["P-ed77659dbe40"]},{"id":"RP-0246920","time":"2026-08-23T05:08:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"모두가 잠에 든 야심한 밤","characters":["P-ed77659dbe40"]},{"id":"RP-0246921","time":"2026-08-23T05:08:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"존은 방금 전 딘과의 대화를 떠올리고 있습니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246922","time":"2026-08-23T05:09:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"어떤 학파에선 한명의 사람을 곧 하나의 소우주로 바라봅니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246923","time":"2026-08-23T05:09:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"즉, 사람과 사람 사이의 대화란, 세계와 세계가 나누는 언어이고","characters":["P-ed77659dbe40"]},{"id":"RP-0246924","time":"2026-08-23T05:09:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"이는 또한 주문, 마법이라 할 수 있을겁니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246925","time":"2026-08-23T05:10:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"우리는 모두 각자이자 서로의 세계입니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246926","time":"2026-08-23T05:10:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"각 세계가 그 세계만의 색을 가지고있고, 살아가며 자신의 색으로 더 커다란 대우주를 물들입니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246927","time":"2026-08-23T05:10:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그렇다면, 대우주는 뭘까요? 단순히 우리가 살아가는 이 땅? 아니면 저 너른 하늘?","characters":["P-ed77659dbe40"]},{"id":"RP-0246928","time":"2026-08-23T05:11:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"푸른 하늘에 떠다니는 구름, 밤하늘의 별과 달, 아니면 있는지 없는지 누구도 확신하지 못할 죽음 이후의 세계?","characters":["P-ed77659dbe40"]},{"id":"RP-0246929","time":"2026-08-23T05:12:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"어디서부터 어디까지를 세계라고 봐야할까요","characters":["P-ed77659dbe40"]},{"id":"RP-0246930","time":"2026-08-23T05:12:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"우리는 대체 어디까지의 세계를 알고 있는걸까요?","characters":["P-ed77659dbe40"]},{"id":"RP-0246931","time":"2026-08-23T05:12:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"우리가 보고있는 것이 과연 세계의 전부일까요?","characters":["P-ed77659dbe40"]},{"id":"RP-0246932","time":"2026-08-23T05:13:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"확실하게 대답할 수 있는 것이 하나있다면..... 우리가 보는 것은 아주아주 작고 작은 파편 중에서도 한쪽의 면 뿐일 것이라는 겁니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246933","time":"2026-08-23T05:15:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"색, 법 수, 상, 행부터 우리의 인지 기관인 안이비설촉의, 말나, 아라야까지의 8가지 식까지","characters":["P-ed77659dbe40"]},{"id":"RP-0246934","time":"2026-08-23T05:15:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"우리가 보는 일곱빛의 무지개부터, 저 밤하늘을 비추는 별과 별 사이의 어둠까지","characters":["P-ed77659dbe40"]},{"id":"RP-0246935","time":"2026-08-23T05:16:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"가장 작은 물 한방울부터 너른 대해의 푸른 수평선까지","characters":["P-ed77659dbe40"]},{"id":"RP-0246936","time":"2026-08-23T05:16:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"우리의 시야는, 우리의 감각은 아주아주 좁고 편협합니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246937","time":"2026-08-23T05:17:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"내가 느끼는 즐거움은 누군가에겐 불쾌할 수 있고, 나의 슬픔이 누군가의 기쁨일 수 있는 것처럼","characters":["P-ed77659dbe40"]},{"id":"RP-0246938","time":"2026-08-23T05:17:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"소우주와 소우주는 각각이 다른 색채를 품고서, 서로에게 스며들어갑니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246939","time":"2026-08-23T05:18:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그렇다면 대우주란... 우리가 살아가는 세계란...","characters":["P-ed77659dbe40"]},{"id":"RP-0246940","time":"2026-08-23T05:18:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"아주 크고 새하얀 도화지일 것입니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246941","time":"2026-08-23T05:18:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그리고 사람과 사람이 내딛는 발걸음마자 형형색색의 궤적이 남을 겁니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246942","time":"2026-08-23T05:18:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그 궤적이, 점들이 이어지며 하나의 선을 만들고","characters":["P-ed77659dbe40"]},{"id":"RP-0246943","time":"2026-08-23T05:19:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그렇게 만들어진 선들이 면을 이루고","characters":["P-ed77659dbe40"]},{"id":"RP-0246944","time":"2026-08-23T05:19:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그 위를 또다시 누군가 밟고 걸어나가며 색들이 겹겹이 쌓여간다면","characters":["P-ed77659dbe40"]},{"id":"RP-0246945","time":"2026-08-23T05:20:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"어쩌면, 우리의 세계는 우리의 눈으로 보는 것보다 훨씬 다채롭고 아름다울지도 모릅니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246946","time":"2026-08-23T05:20:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"존이라는 한명의 사람이자 마법사가 하늘을 올려다보았습니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246947","time":"2026-08-23T05:21:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"쏟아질 것처럼 수많은 별들이 빛나는 하늘은, 그 어느때보다 짙은 검은 색이었지만","characters":["P-ed77659dbe40"]},{"id":"RP-0246948","time":"2026-08-23T05:21:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"그에겐 동시에 또한 찬란한 색으로 비췄을지 모릅니다","characters":["P-ed77659dbe40"]},{"id":"RP-0246949","time":"2026-08-23T05:21:00+09:00","room":"RP","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-ed77659dbe40"]},{"id":"RP-0246950","time":"2026-08-23T05:21:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
